  const found=monsterCatalog().find(m=>m.mapIndex===mapIndex&&m.kind===baseKind&&m.material===e?.mat) || monsterCatalog().find(m=>m.mapIndex===mapIndex&&m.kind===baseKind&&m.name===String(e?.name||'').replace(/^菁英・/,''));
